from pathlib import Path
import re,json,html,datetime
MODELS=[{'slug': 'vaas-rugzak', 'name': 'Rugzak tasvaas', 'color': 'Groen', 'prices': (4995, 6995, 9495), 'kind': 'Tasvazen'}, {'slug': 'vaas-clutch', 'name': 'Clutch tasvaas', 'color': 'Donkerblauw', 'prices': (3995, 5995, 7995), 'kind': 'Tasvazen'}, {'slug': 'vaas-shopper', 'name': 'Shopper tasvaas', 'color': 'Terracotta', 'prices': (3995, 5995, 7995), 'kind': 'Tasvazen'}, {'slug': 'vaas-bucketbag', 'name': 'Bucketbag tasvaas', 'color': 'Beige', 'prices': (4495, 6495, 8995), 'kind': 'Tasvazen'}, {'slug': 'vaas-koffertje', 'name': 'Koffertje tasvaas', 'color': 'Bruin', 'prices': (4995, 6995, 9495), 'kind': 'Tasvazen'}, {'slug': 'vaas-halvemaan', 'name': 'Halvemaan tasvaas', 'color': 'Lila', 'prices': (4495, 6495, 8995), 'kind': 'Tasvazen'}, {'slug': 'vaas-bowlingtas', 'name': 'Bowling tasvaas', 'color': 'Crème', 'prices': (4495, 6495, 8995), 'kind': 'Tasvazen'}, {'slug': 'vaas-zadeltas', 'name': 'Zadel tasvaas', 'color': 'Donkergroen', 'prices': (4995, 6995, 9495), 'kind': 'Tasvazen'}, {'slug': 'vaas-makeuptasje', 'name': 'Make-uptasje vaas', 'color': 'Zachtroze', 'prices': (3495, 4995, 6995), 'kind': 'Tasvazen'}, {'slug': 'vaas-harttas', 'name': 'Hart tasvaas', 'color': 'Bordeauxrood', 'prices': (4495, 6495, 8995), 'kind': 'Tasvazen'}, {'slug': 'vaas-parfum-rond', 'name': 'Ronde parfumvaas', 'color': 'Groen', 'prices': (3495, 4995, 6995), 'kind': 'Parfumvazen'}, {'slug': 'vaas-parfum-octagon', 'name': 'Octagon parfumvaas', 'color': 'Crème', 'prices': (3995, 5995, 7995), 'kind': 'Parfumvazen'}, {'slug': 'vaas-parfum-artdeco', 'name': 'Art deco parfumvaas', 'color': 'Donkerblauw', 'prices': (4495, 6495, 8995), 'kind': 'Parfumvazen'}, {'slug': 'vaas-parfum-druppel', 'name': 'Druppel parfumvaas', 'color': 'Zachtroze', 'prices': (3495, 4995, 6995), 'kind': 'Parfumvazen'}, {'slug': 'vaas-parfum-sculptuur', 'name': 'Sculptuur parfumvaas', 'color': 'Lila', 'prices': (3995, 5995, 7995), 'kind': 'Parfumvazen'}]
TEMPLATE='<!doctype html>\n<html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Cannage tasvaas | Makers 3D Labs</title>\n<meta name="description" content="Cannage tasvaas: kant-en-klaar afgewerkte 3D-vaas in klein, middel en groot. Kies formaat en gewenste kleur.">\n<link rel="stylesheet" href="assets/shop.css"><link rel="stylesheet" href="assets/categorie-paginas.css">\n<style>\n.vase-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:38px;align-items:start;margin-top:24px}\n.vase-image{margin:0;position:sticky;top:24px}.vase-image img{display:block;width:100%;height:auto;aspect-ratio:1;object-fit:contain;background:#1d2936;border-radius:18px}\n.vase-image figcaption{font-size:12px;color:#bdcdda;line-height:1.6;margin-top:12px}\n.vase-kicker{color:#83d7dd;font-size:11px;font-weight:750;letter-spacing:.12em}\n.vase-info h1{font-size:clamp(28px,3.4vw,43px);line-height:1.15;letter-spacing:-.035em;margin:10px 0 17px}\n.vase-intro{color:#c4d3df}.vase-form{padding:22px;background:#213345;border:1px solid #638194;border-radius:16px}\n.vase-form fieldset{border:0;padding:0;margin:0 0 20px;min-width:0}.vase-form legend,.vase-field{font-size:14px;font-weight:750}\n.vase-sizes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:10px}\n.vase-choice{position:relative;cursor:pointer}.vase-choice input{position:absolute;left:10px;top:10px;accent-color:#00afb8;margin:0}\n.vase-choice span{display:block;padding:30px 10px 13px;border:1px solid #7a95a6;border-radius:10px;background:#293f51;color:#fff;font-size:13px}\n.vase-choice input:checked+span{border:2px solid #80dce1;padding:29px 9px 12px;background:#2b4b5b}\n.vase-choice input:focus-visible+span{outline:3px solid #80dce1;outline-offset:3px}\n.vase-field{display:block;margin-top:18px}\n.vase-form input[type=text],.vase-form input[type=number]{display:block;width:100%;margin-top:7px;padding:12px;background:#172a38;color:#fff;border:1px solid #7891a4;border-radius:9px;font:inherit}\n.vase-form input::placeholder{color:#afc2cf;opacity:1}\n.vase-hint{color:#b8cbd8;font-size:12px;line-height:1.6;margin:8px 0 15px}\n.vase-price{margin-top:20px;padding-top:18px;border-top:1px solid #ffffff30}\n.vase-price strong{font-size:30px;color:#8ce1e4}.vase-unit{font-size:13px;color:#c4d3df}\n.vase-summary{white-space:pre-line;font-size:13px;color:#dce9f2}\n.vase-submit{width:100%;padding:14px;border:1px solid #00afb8;border-radius:10px;background:#00afb8;color:#082d34;font:750 15px Arial,sans-serif;cursor:pointer}\n.vase-submit:hover{background:#77dce1}.vase-error{font-size:13px;color:#ffcfb8}\n.vase-details{margin-top:20px;border:1px solid #638194;border-radius:12px;background:#213345;overflow:hidden}\n.vase-details summary{padding:14px 17px;color:#fff;cursor:pointer;font-weight:700}.vase-details div{padding:0 18px 16px;color:#c4d3df;font-size:13px}.vase-details ul{margin:0;padding-left:18px}\n@media(max-width:800px){.vase-layout{grid-template-columns:1fr;gap:24px}.vase-image{position:static;max-width:550px;margin:auto}}\n@media(max-width:420px){.vase-form{padding:17px}.vase-sizes{grid-template-columns:1fr}.vase-choice span{padding:12px 12px 12px 34px}.vase-choice input:checked+span{padding:11px 11px 11px 33px}.vase-choice input{top:15px}}\n</style><link rel="stylesheet" href="assets/vaas-kleuren.css"></head><body>\n<header class="category-header"><div class="head-inner"><a href="index.html" aria-label="Makers 3D Labs — Home"><img src="makers3dlabs-logo.webp" alt="Makers 3D Labs" width="1600" height="500"></a><nav class="category-nav" aria-label="Hoofdnavigatie"><a href="index.html">Home</a><a href="winkel.html">Webshop</a></nav></div></header>\n<main class="category-main"><a class="category-crumb" href="categorie-bloemenvazen.html">← Terug naar Bloemenvazen</a>\n<div class="vase-layout"><figure class="vase-image"><img src="vaas-dior-tas-voorbeeld.webp" alt="Cannage tasvaas — AI-voorbeeldontwerp met bloemen" width="1254" height="1254">\n<figcaption>AI-voorbeeldontwerp, Dior-geïnspireerd. Geen officieel merkproduct. Kant-en-klaar afgewerkte vaas; bloemen en waterdichte binnenvaas niet inbegrepen. Definitieve uitvoering en beschikbaarheid bevestigen we vooraf.</figcaption></figure>\n<section class="vase-info" aria-labelledby="vase-title"><span class="vase-kicker">TASVAZEN · KANT-EN-KLAAR</span><h1 id="vase-title">Cannage tasvaas</h1>\n<p class="vase-intro">Een decoratieve 3D-geprinte vaas, Dior-geïnspireerd. Alleen kant-en-klaar afgewerkt verkrijgbaar. Kies klein, middel of groot en geef je gewenste kleuren door.</p>\n<form id="vase-form" class="vase-form">\n<fieldset><legend>1. Kies jouw formaat</legend><div class="vase-sizes">\n<label class="vase-choice"><input type="radio" name="size" value="15" checked required><span><b>Klein · 15 cm</b><br>€ 44,95</span></label>\n<label class="vase-choice"><input type="radio" name="size" value="20"><span><b>Middel · 20 cm</b><br>€ 64,95</span></label>\n<label class="vase-choice"><input type="radio" name="size" value="25"><span><b>Groot · 25 cm</b><br>€ 89,95</span></label>\n</div><p class="vase-hint">Totale hoogte van de vaas, zonder bloemen; inclusief handvat bij tasmodellen. Breedte en diepte schalen mee met het model.</p></fieldset>\n<label class="vase-field" for="vase-color">2. Gewenste kleur van de vaas<input id="vase-color" name="color" value="Crème" type="text" list="vase-colors" required maxlength="60" placeholder="Bijvoorbeeld crème, zwart, zachtroze of een eigen kleur"></label>\n<datalist id="vase-colors"><option value="Crème"><option value="Wit"><option value="Zwart"><option value="Zachtroze"><option value="Beige"><option value="Rood"><option value="Groen"><option value="Blauw"><option value="Turquoise"><option value="Goud"><option value="Zilver"></datalist>\n<p class="vase-hint">Alle kleuren zijn aan te vragen: kies een suggestie of typ jouw eigen kleur. Beschikbaarheid en eventuele meerprijs voor speciale kleuren of afwerkingen worden vooraf bevestigd.</p>\n<label class="vase-field" for="vase-letters">3. Gewenste kleur van de details<input id="vase-letters" name="letters" type="text" list="letter-colors" required maxlength="60" value="Goud"></label>\n<datalist id="letter-colors"><option value="Goud"><option value="Zilver"><option value="Wit"><option value="Zwart"><option value="Dezelfde kleur als de vaas"></datalist>\n<label class="vase-field" for="vase-qty">4. Aantal<input id="vase-qty" name="qty" type="number" min="1" max="100" step="1" required value="1"></label>\n<div class="vase-price" aria-live="polite" aria-atomic="true"><strong id="vase-total">€ 44,95</strong><div id="vase-unit" class="vase-unit">€ 44,95 per stuk</div><p id="vase-summary" class="vase-summary"></p></div>\n<p class="vase-hint">Zonder bloemen en exclusief verzending. Dit is een aanvraag; de definitieve uitvoering, prijs en levertijd worden vóór de bestelling bevestigd.</p>\n<p id="vase-error" class="vase-error" role="alert"></p><button class="vase-submit" type="submit">Vraag deze vaas aan →</button>\n<p class="vase-hint">Je keuzes gaan mee naar het aanvraagformulier. Daar vul je jouw contactgegevens in. Online afrekenen is nog niet actief.</p>\n</form>\n<details class="vase-details"><summary>Gebruik en uitvoering</summary><div><ul><li>Decoratieve 3D-print; fijne printlijnen kunnen zichtbaar zijn.</li><li>Voor droogbloemen en kunstbloemen.</li><li>Gebruik voor verse bloemen alleen een passende waterdichte binnenvaas. Die is niet inbegrepen.</li><li>De waterdichtheid van de print zelf is niet bevestigd; vul de print niet rechtstreeks met water.</li><li>De kleur kan op een beeldscherm iets afwijken.</li><li>Levertijd en definitieve uitvoering worden vooraf bevestigd.</li></ul></div></details>\n</section></div></main>\n<script>\nconst vf=document.getElementById(\'vase-form\'),vp={\'15\':4495,\'20\':6495,\'25\':8995},vn={\'15\':\'Klein\',\'20\':\'Middel\',\'25\':\'Groot\'};\nconst veuro=c=>new Intl.NumberFormat(\'nl-NL\',{style:\'currency\',currency:\'EUR\'}).format(c/100);\nfunction vaseSelection(){const d=new FormData(vf),size=d.get(\'size\');return {size,color:String(d.get(\'color\')||\'\').trim(),letters:String(d.get(\'letters\')||\'\').trim(),qty:Number(d.get(\'qty\')),price:vp[size]};}\nfunction updateVase(){\n const s=vaseSelection(),valid=Number.isInteger(s.qty)&&s.qty>=1&&s.qty<=100;\n document.getElementById(\'vase-total\').textContent=valid?veuro(s.price*s.qty):\'Kies een geldig aantal\';\n document.getElementById(\'vase-unit\').textContent=veuro(s.price)+\' per stuk\';\n document.getElementById(\'vase-summary\').textContent=vn[s.size]+\' · \'+s.size+\' cm totale hoogte\'+(s.color?\'\\nVaaskleur: \'+s.color:\'\')+(s.letters?\'\\nDetailkleur: \'+s.letters:\'\');\n}\nvf.addEventListener(\'input\',updateVase);vf.addEventListener(\'change\',updateVase);updateVase();\nvf.addEventListener(\'submit\',event=>{\n event.preventDefault();const s=vaseSelection(),error=document.getElementById(\'vase-error\');\n if(!Object.hasOwn(vp,s.size)||!s.color||!s.letters||!Number.isInteger(s.qty)||s.qty<1||s.qty>100){error.textContent=\'Kies een formaat, vul beide kleuren in en kies een aantal van 1 tot 100.\';return;}\n const description=[\'Cannage tasvaas — Dior-geïnspireerd\',\'Uitvoering: kant-en-klaar afgewerkt\',\'Formaat: \'+vn[s.size]+\' — \'+s.size+\' cm totale hoogte\',\'Kleur vaas: \'+s.color,\'Kleur details: \'+s.letters,\'Aantal: \'+s.qty,\'Prijs per stuk: \'+veuro(s.price),\'Producttotaal exclusief verzending: \'+veuro(s.price*s.qty),\'Zonder bloemen en zonder waterdichte binnenvaas.\',\'Definitieve kleuren, uitvoering en levertijd graag bevestigen.\'].join(\'\\n\');\n try{sessionStorage.setItem(\'makers-collectievaas-aanvraag\',JSON.stringify({description,qty:s.qty}));}\n catch(e){error.textContent=\'Je browser kan de keuzes niet bewaren. Sta sessieopslag toe en probeer opnieuw.\';return;}\n location.href=\'contact.html?product=Collectievaas#quoteForm\';\n});\n</script><script src="assets/shop-data.js"></script><script src="assets/shop.js"></script><script src="assets/vaas-kleuren.js"></script></body></html>\n'

root=Path.cwd()
categorypath=root/'categorie-bloemenvazen.html'
required=['categorie-bloemenvazen.html','contact.html','assets/vaas-kleuren.js','assets/vaas-kleuren.css']+[m['slug']+'-voorbeeld.webp' for m in MODELS]
missing=[p for p in required if not (root/p).is_file()]
if missing:raise SystemExit('Upload eerst de uitgepakte bestanden naar GitHub en voer git pull uit. Ontbrekend: '+', '.join(missing))
category=categorypath.read_text(encoding='utf-8')
marker='<div class="category-products" id="category-products">'
if marker not in category:raise SystemExit('Categorie-opmaak niet herkend; niets gewijzigd.')
if any((root/(m['slug']+'.html')).exists() for m in MODELS):raise SystemExit('Nieuwe vaaspagina’s bestaan al; niets overschreven.')
def euro(p):return '€ '+f'{p/100:.2f}'.replace('.',',')
allcolors=['Wit','Crème','Beige','Zwart','Grijs','Bruin','Rood','Bordeauxrood','Roze','Zachtroze','Oranje','Perzik','Geel','Groen','Donkergroen','Blauw','Donkerblauw','Turquoise','Paars','Lila','Goud','Zilver','Terracotta','Andere kleur']
files={};cards=[]
for m in MODELS:
    slug,name,kind=m['slug'],m['name'],m['kind']
    small,medium,large=m['prices']
    page=TEMPLATE
    replacements={'4495':str(small),'6495':str(medium),'8995':str(large),'€ 44,95':euro(small),'€ 64,95':euro(medium),'€ 89,95':euro(large)}
    page=re.sub(r'€ 44,95|€ 64,95|€ 89,95|4495|6495|8995',lambda x:replacements[x[0]],page)
    page=page.replace('Cannage tasvaas',name).replace('Dior-geïnspireerd','een eigen ontwerp').replace('Geen officieel merkproduct. ','')
    page=page.replace('vaas-dior-tas-voorbeeld.webp',slug+'-voorbeeld.webp')
    page=page.replace('TASVAZEN · KANT-EN-KLAAR',kind.upper()+' · KANT-EN-KLAAR')
    page=page.replace('name="color" value="Crème"','name="color" value="'+m['color']+'"')
    if slug=='vaas-parfum-sculptuur':page=page.replace('value="Goud"></label>','value="Zilver"></label>')
    files[slug+'.html']=page
    encoded=html.escape(json.dumps(allcolors,ensure_ascii=False),quote=True)
    cards.append(f'<article id="{slug}-product" class="category-product" data-name="{name}" data-colors="{encoded}" data-kind="{kind}" data-price="{small}" data-personal="false"><a class="category-product-photo" href="{slug}.html"><img src="{slug}-voorbeeld.webp" alt="{name} — voorbeeldontwerp" loading="lazy" width="1254" height="1254"></a><div class="category-product-body"><span class="category-product-type">{kind} · kant-en-klaar</span><h2>{name}</h2><p>Alle kleuren mogelijk · klein, middel en groot</p><strong class="category-price">Vanaf {euro(small)}</strong><a class="category-product-link" href="{slug}.html">Kies kleur en formaat →</a></div></article>')
category=category.replace(marker,marker+''.join(cards),1)
count=len(re.findall(r'<article\b[^>]*class="category-product"',category))
category=re.sub(r'(<p id="category-count"[^>]*>).*?(</p>)',lambda x:x[1]+str(count)+' producten'+x[2],category,count=1,flags=re.S)
files['categorie-bloemenvazen.html']=category
stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
backup=root/'backups'/('extra-vazen-'+stamp)
backup.mkdir(parents=True,exist_ok=True)
(backup/categorypath.name).write_bytes(categorypath.read_bytes())
for filename,content in files.items():(root/filename).write_text(content,encoding='utf-8')
print('Klaar: 15 extra vazen toegevoegd. Alle kleuren, 15/20/25 cm, prijzen en aanvraagformulier gekoppeld. Nog niet gepubliceerd.')
